	const walk = async (prefix) => {
		for (const item of await readdir(join(home, prefix), { withFileTypes: true })) {
			const name = prefix + item.name;
			if (item.isSymbolicLink()) throw Error("VIDEO_PATH_DENIED");
			if (item.isDirectory()) {
				if (!directories.has(name)) throw Error("VIDEO_PROFILE_INVALID");
				await walk(name + "/");
			} else if (!item.isFile() || !expected.has(name) && name !== "profiles/studybuddy-video/cordis.yml") throw Error("VIDEO_PROFILE_INVALID");
		}
	};
